const listOwnedTaskEvents = `-- name: ListOwnedTaskEvents :many
SELECT event.id, event.task_id, event.status, event.code, event.params,
       event.progress_percent, event.created_at
FROM component_repo.task_events event
JOIN component_repo.tasks task ON task.id = event.task_id
WHERE event.task_id = $1 AND task.owner_id = $2
ORDER BY event.created_at, event.id
`

type ListOwnedTaskEventsParams struct {
	TaskID  pgtype.UUID
	ActorID pgtype.UUID
}

func (q *Queries) ListOwnedTaskEvents(ctx context.Context, arg ListOwnedTaskEventsParams) ([]ComponentRepoTaskEvent, error) {
	rows, err := q.db.Query(ctx, listOwnedTaskEvents, arg.TaskID, arg.ActorID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ComponentRepoTaskEvent{}
	for rows.Next() {
		var i ComponentRepoTaskEvent
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.Status,
			&i.Code,
			&i.Params,
			&i.ProgressPercent,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

